INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5513791, 794539, 43774, '<td valign="top">That''s pretty amazing. This looks a bit familiar, maybe I''ve seen a pic of it before. I really like it.</td>', 'That''s pretty amazing. This looks a bit familiar, maybe I''ve seen a pic of it before. I really like it.', '2009-06-04 10:46:59.000000', NULL, 1),
(5513810, 794679, 57460, '<td valign="top">I really love the simplicity in this photo!  At first I was a little put off by the very shallow DOF, but then I saw the ant and I think the use of the shallow DOF works wonderful here.  This photo sure invokes some great emotions - strength, encouragement, empowerment - it reminds me how no matter how small or insignificant one may seem - they can be more powerful than imaginable.  <br/> <br/>I think this photo would have much more of an impact as a whole with a different crop - maybe cropping out the top of the photo.  For this, I cant give a perfect 10, but for the pure emotion invoked by the photo and the unique capture  I give it a 9!  And I am adding this as a favorite!<br/> <br/><i>ETA:</i> <br/>Okay  I just cannot get this photo out of my head.  There is something about it that is haunting me!  I love the graininess of it!  I love the almost surrealistic qualities of it!  I really just only wish it had a different crop.  I usually dont do this  but since I absolutely cannot get this photo out of my mind, you deserve the extra point.  This is a 10  regardless of the crop!  This is a 10 purely for the artistic qualities of this photo and the emotion it invokes!<br/> <br/>I love b/w surrealistic/artistic movies (I just got done watching Eraserhead yesterday).  This photo makes me think of the beautiful cinematography of those movies (not the feelings of Eraserhead  but other b/w artistic/surreal movies  like my favorite movie Pi).  I am only mentioning this because these movies invoke so many emotions and they are so beautiful.  And that is the same feeling I am getting with your photo here.  <br/> <br/>It is one thing to have a pretty photo that fits into the same cookie cutter shape of other pretty photos  but it is something so much more to have such a beautiful, emotionally captivating photo such as yours here  even with the simplicity of the subject  I think that is what makes it more emotionally captivating, because it invites the viewers own emotions into the photo.<br/> <br/>I know I am now just rambling  but I am very bad about turning my emotions into words  and I really want you to know how this photo has enthralled me!<br/> <br/> <br/><i>One more ETA:</i> <br/> <br/>Okay  I dont mean to keep coming back to your photo, but I just cant help myself.  In my last comments I had said that I thought it could use a different crop.  I was viewing your photo on my laptop last night with a small resolution, so I was not able to see the entire photo on my screen at once.  Now that I am at work and am able to look at it in its entirety on my monitors, I must say I really do love the crop you choose.  The in focus area of the concrete on the top gives almost the illusion of a starry sky above the main subject, and the light OOF area behind the subject gives the illusion of a horizon in the distance.  It sure does help add to the surrealistic qualities of the photo!<br/> <br/>I am dieing to know whose photo this is!<br/> <br/>I will try not to come back and add to my already LONG comment  but I cant make any promises!  I just cant pull myself away from your photo!</td>', 'I really love the simplicity in this photo!  At first I was a little put off by the very shallow DOF, but then I saw the ant and I think the use of the shallow DOF works wonderful here.  This photo sure invokes some great emotions - strength, encouragement, empowerment - it reminds me how no matter how small or insignificant one may seem - they can be more powerful than imaginable.   I think this photo would have much more of an impact as a whole with a different crop - maybe cropping out the top of the photo.  For this, I cant give a perfect 10, but for the pure emotion invoked by the photo and the unique capture  I give it a 9!  And I am adding this as a favorite! ETA: Okay  I just cannot get this photo out of my head.  There is something about it that is haunting me!  I love the graininess of it!  I love the almost surrealistic qualities of it!  I really just only wish it had a different crop.  I usually dont do this  but since I absolutely cannot get this photo out of my mind, you deserve the extra point.  This is a 10  regardless of the crop!  This is a 10 purely for the artistic qualities of this photo and the emotion it invokes! I love b/w surrealistic/artistic movies (I just got done watching Eraserhead yesterday).  This photo makes me think of the beautiful cinematography of those movies (not the feelings of Eraserhead  but other b/w artistic/surreal movies  like my favorite movie Pi).  I am only mentioning this because these movies invoke so many emotions and they are so beautiful.  And that is the same feeling I am getting with your photo here.   It is one thing to have a pretty photo that fits into the same cookie cutter shape of other pretty photos  but it is something so much more to have such a beautiful, emotionally captivating photo such as yours here  even with the simplicity of the subject  I think that is what makes it more emotionally captivating, because it invites the viewers own emotions into the photo. I know I am now just rambling  but I am very bad about turning my emotions into words  and I really want you to know how this photo has enthralled me!  One more ETA:  Okay  I dont mean to keep coming back to your photo, but I just cant help myself.  In my last comments I had said that I thought it could use a different crop.  I was viewing your photo on my laptop last night with a small resolution, so I was not able to see the entire photo on my screen at once.  Now that I am at work and am able to look at it in its entirety on my monitors, I must say I really do love the crop you choose.  The in focus area of the concrete on the top gives almost the illusion of a starry sky above the main subject, and the light OOF area behind the subject gives the illusion of a horizon in the distance.  It sure does help add to the surrealistic qualities of the photo! I am dieing to know whose photo this is! I will try not to come back and add to my already LONG comment  but I cant make any promises!  I just cant pull myself away from your photo!', '2009-06-04 11:04:57.000000', NULL, 1),
(5513816, 791007, 3149, '<td valign="top">Good composition here...  I love old trees.  You should try a grad ND filter to help cut down on over-exposure.  Good luck!</td>', 'Good composition here...  I love old trees.  You should try a grad ND filter to help cut down on over-exposure.  Good luck!', '2009-06-04 11:16:25.000000', NULL, 1),
