(5519275, 795551, 80904, '<td valign="top">Grats on 85th place. You are improving!! Keep up the good work.</td>', 'Grats on 85th place. You are improving!! Keep up the good work.', '2009-06-08 01:29:57.000000', NULL, 0),
(5519276, 795158, 60698, '<td valign="top">What?? This score doesn''t make sense. Should have been much higher. This is an amazing photo! Very natural, beautiful with good light and background. Very scary to someone like me who only takes photos of bears in zoos. Making it a favorite!</td>', 'What?? This score doesn''t make sense. Should have been much higher. This is an amazing photo! Very natural, beautiful with good light and background. Very scary to someone like me who only takes photos of bears in zoos. Making it a favorite!', '2009-06-08 01:30:01.000000', NULL, 0),
