INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5519394, 795084, 20324, '<td valign="top">Thanks for  voting and the comments. The picture was processed from one exposure, it was tone mapped in Photomatix, but I wouldn''t say that  it was done with HDR technique. The blue sky cast on the left is how it was at the moment of taking the picture, and it looks the same way on the original. I have to admit that Scotland is a beautiful place, and very photogenic IMO, a highly recommended spot for a photographic adventure.</td>', 'Thanks for  voting and the comments. The picture was processed from one exposure, it was tone mapped in Photomatix, but I wouldn''t say that  it was done with HDR technique. The blue sky cast on the left is how it was at the moment of taking the picture, and it looks the same way on the original. I have to admit that Scotland is a beautiful place, and very photogenic IMO, a highly recommended spot for a photographic adventure.', '2009-06-08 02:51:16.000000', NULL, 0),
(5519395, 794401, 68586, '<td valign="top">Andi - brilliant concept and execution.</td>', 'Andi - brilliant concept and execution.', '2009-06-08 02:51:16.000000', NULL, 0),
